import math

# Tolerance for floating point comparisons
EPSILON = 1e-6
k_target = 2310
alpha_val = math.sqrt(2)

def E(m, n, alpha):
    """Calculates the pretty pair function value E(m, n)."""
    if m <= 0 or n <= 0:
        # Should not happen for the checks below, but defensive programming.
        return float('inf') 
    try:
        return m * math.ceil(n * alpha) - n * math.floor(m * alpha)
    except OverflowError:
        return float('inf')

def is_pretty(m, n, k, alpha):
    """Checks if the pair (m, n) is pretty for a given k."""
    if m <= 0 or n <= 0:
        return False
    val = E(m, n, alpha)
    return abs(val - k) < EPSILON

